[s1,s2,s3,s4,r1,r2,l1,l2,c1,c2,c3,c4,x1,x2,x3,x4] = powericon('Parallel RLC Load',ActivePower,InductivePower,CapacitivePower,UnbalancedPower,Pabc,QLabc,QCabc,Pabcp,QLabcp,QCabcp,Configuration);
ground = Configuration==1;
neutral = Configuration==3;
